package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.io.NumberInput;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.text.FieldPosition;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StdDateFormat#isLenient
 */
public class StdDateFormat_isLenient_TriageGen1Test {







    @Test
    public void testIsLenientAfterClone() {
        // Test that cloning preserves the lenient state
        StdDateFormat df = new StdDateFormat();
        df.setLenient(false);
        StdDateFormat cloned = df.clone();
        assertFalse("Cloned object should preserve lenient state (false)", cloned.isLenient());

        df.setLenient(true);
        cloned = df.clone();
        assertTrue("Cloned object should preserve lenient state (true)", cloned.isLenient());
    }
}
